INSERT INTO `plan` VALUES ('0bbc7bb5-3eff-464d-a27d-05be8baf792a', '关于开展 2026 年“科学家精神教育基地” 申报工作的通知', '（1）申报条件：①申报主体主要包括科技馆、重大科技工程纪念馆（遗迹）、科研机构和科创平台（企业）、科技人物纪念馆（故旧居）等。②有独立的展馆，或相对独立的展厅和展览空间。③展馆（展厅）的主要内容，必须是以宣传讲述科学家或创新团队、科研群体爱国创新、求实奉献、协同育人的故事和精神为主，不是单纯的科学技术普及、青少年科学培训或者科研成就和装备的展览展示。④有一定数量的珍贵实物，包括书信、手稿、图纸、证章、照片、历史影像等。⑤有比较规范的管理制度和讲解团队。⑥经常性面向社会公众特别是青少年开放，组织各类科学家⑦精神宣传教育活动，开发制作适于传播的宣传产品。', '0fde0037-edf8-11f0-8623-6018953679ef', '2026-04-10', '2026-04-15', '8a09e425-f911-11f0-b532-6018953679ef', 'addeec73-f911-11f0-b532-6018953679ef', 'admin', '6a0c0e54-5b2e-45e2-9c27-6c6054acccd2', '周敏香', 'c4c19e08-edf7-11f0-8623-6018953679ef', 'd2f54395-7a48-4f71-bb92-ee00d4a84144', '', '2026-04-13 11:12:15', '2026-04-15 08:23:43', '0', '1', '1');
