INSERT INTO `plan` VALUES ('94d83943-f98b-4ab2-a876-d6530f85ad74', '关于征集“浙里科普”专家库入库专家及科普资源的通知', '“浙里科普”专家库入库专家要求（满足至少2项以下条件）：①专业资历深厚：具有副高级及以上专业技术职称或同等专业水平，从事相关专业工作5年以上；②科普经验丰富：作为主要成员（前三位）承担过省、厅级科普项目，或获得过省、厅级科普作品创作大赛奖项；具有丰富的科普活动策划、组织或评审经验；③科普成果显著：正式出版过科普著作、译著或科普教材；④组织协调能力强：在科技社团、科研机构、高等院校或相关企业中担任一定管理职务，具有较强的组织协调能力和广泛的业界联系，能够有效推动科普资源的整合与共享。', '0fde0037-edf8-11f0-8623-6018953679ef', '2026-04-02', '2026-04-28', '8a09e425-f911-11f0-b532-6018953679ef', 'addeec73-f911-11f0-b532-6018953679ef', 'admin', '6a0c0e54-5b2e-45e2-9c27-6c6054acccd2', '周敏香', 'c4c19e08-edf7-11f0-8623-6018953679ef', 'd2f54395-7a48-4f71-bb92-ee00d4a84144', '', '2026-04-09 11:34:06', '2026-04-29 09:08:47', '0', '1', '1');
