INSERT INTO `plan` VALUES ('cb3fd48e-96fd-4524-9b13-38b322e54631', '浙江省科学技术协会关于开展第九批浙江省科普教育基地授牌命名工作的通知', '申报条件：①具有法人资格或受法人正式委托，独立开展科普活动的单位。②愿意承担科普工作责任，主动将科普工作纳入单位发展规划，自主申报科普教育基地。③所开展的业务具有明确的科普内容，充分体现业务类技术的专业要求。重点是能为正常开展科普活动提供专业性保障;为杜绝伪科学、假科普的传播提供健全的防范机制保障;为群众高度参与、公众喜闻乐见的科普活动提供互动性保障。④已经开展科普工作，取得了一定的科普业绩，并在社会上形成了较好的影响力，可持续为公众提供优质科普服务。⑤突出“四个面向”:在内容展示上，突出“科技前沿可视化”在传播手段上，实现“科学传播智能化”:在科普方式上，突出体验式、互动式;在功能定位上，成为“创新生态的助推器”。鼓励我省“315”科技创新体系和“415X”先进制造业集群的前沿科技领域相关单位，国家和省实验室、省技术创新中心、大科学装置、大科学计划、研究院等具有前沿科学启示和普及教育优势的重大科研机构和主要科创平台申报省级科普教育基地。⑥符合《浙江省科普教育基地认定与管理办法》《关于进一步优化科普教育基地业务类技术认定的补充规定》的其他规定。', '0fde0037-edf8-11f0-8623-6018953679ef', '2026-04-10', '2026-04-22', '8a09e425-f911-11f0-b532-6018953679ef', 'addeec73-f911-11f0-b532-6018953679ef', 'admin', '6a0c0e54-5b2e-45e2-9c27-6c6054acccd2', '周敏香', 'c4c19e08-edf7-11f0-8623-6018953679ef', 'd2f54395-7a48-4f71-bb92-ee00d4a84144', '', '2026-04-13 11:13:16', '2026-04-24 15:32:47', '0', '1', '1');
