INSERT INTO `works` VALUES ('eb33c230-faf6-461e-85ae-98b60e21fb03', '浙江省科学技术厅 浙江省教育厅关于组织开展2026年浙江省“科技副总”选聘工作的通知', '1.关于续聘：已参与2025年选聘且协议期限为2025年至2027年的科技副总，如与企业合作良好并有意继续合作的，请重新签订并上传《科技副总三方协议》。新协议期限自2026年起，可根据实际合作情况签订2年及以上。\n2.关于更换派驻企业：2025年科技副总协议仍在有效期内的，须先解除原协议，方可派驻至新企业担任科技副总。\n3.关于兼聘：已参与市级科技副总选聘的，可同时参与省级科技副总选聘。', '2026-04-22', '2026-05-20', '8a09e425-f911-11f0-b532-6018953679ef', 'addeec73-f911-11f0-b532-6018953679ef', 'admin', '0e569ae5-c429-4967-a0f6-4ddaafaaeb3e', '周敏香', '2c89ecaf-010f-4a3a-bd31-8b56eb246219', '', '2026-04-22 10:46:23', '2026-05-06 09:51:41', '0', '1', '1');
